use xiom.io;

use xiom.string;
fn pair_them[T](first: T, second: T) -> Vec[T] {
  let result: Vec[T] = Vec[T].new();
  result.push(first);
  result.push(second);
  return result;
}

fn pick_first[T](items: &Vec[T]) -> Option[T] {
  return items.get(0);
}

fn main() -> Int {
  let nums = pair_them(1, 2);
  io.println(nums.len().to_str());

  let words = pair_them("hi", "bye");
  io.println(words.len().to_str());

  let first_num = pick_first(&nums);
  io.println(match first_num {
    Some(n) => "First: " + to_string(n),
    None => "Empty",
  });
  return 0;
}
